<template>
  <div class="wrapper" :class="{ progress: watched }">
    <div class="video-player" @click="togglePlayPause">
      <video
        ref="videoPlayer"
        class="video-js vjs-default-skin"
        preload="auto"
        width="100%"
        height="100%"
        @ended="onVideoEnded"
      ></video>
      <!-- Overlay that appears when video ends to block YouTube suggestions -->
      <div v-if="isYouTubeVideo() && videoEnded" class="video-ended-overlay">
        <div class="overlay-content">
          <p>Video Complete</p>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import videojs from 'video.js';
import 'video.js/dist/video-js.css';
// Import YouTube plugin
import 'videojs-youtube';

export default {
  name: "VideoPlayer",
  props: {
    video: {
      type: Object,
      required: true,
    },
    index: {
      type: Number,
      required: true
    }
  },
  data() {
    return {
      player: null,
      fullscreen: false,
      watched: false,
      videoEnded: false // New property to track end state
    }
  },
  methods: {
    setupPlayer() {
      // For YouTube videos, use a different approach to lock down the player
      if (this.isYouTubeVideo()) {
        const videoOptions = {
          techOrder: ['youtube'],
          sources: [{
            type: 'video/youtube',
            src: this.getVideoUrl()
          }],
          // Completely custom control bar with minimal options
          controls: false, // We'll handle play/pause with our own click handler
          youtube: {
            // These options lock down the YouTube player
            ytControls: 0, // Hide all YouTube controls
            rel: 0, // Don't show related videos
            showinfo: 0, // Hide video title
            iv_load_policy: 3, // Hide annotations
            modestbranding: 1, // Hide YouTube logo as much as possible
            disablekb: 1, // Disable keyboard controls
            playsinline: 1, // Play inline on mobile
            fs: 0, // Hide fullscreen button (we'll handle fullscreen ourselves)
            loop: 0,
            autoplay: 0,
            enablejsapi: 1,
            origin: window.location.origin,
            // Disabling end screen explicitly
            endscreen: 0,
            hl: 'en',
            cc_load_policy: 0,
            autohide: 1,
            wmode: 'opaque',
            html5: 1
          }
        };
        
        this.player = videojs(this.$refs.videoPlayer, videoOptions);
        this.player.on('ended', this.onVideoEnded);
      } else {
        // For normal HTML5 videos
        const videoOptions = {
          controls: false,
          autoplay: false,
          preload: 'auto',
          poster: this.getVideoPoster(),
          sources: [{
            src: this.getVideoUrl(),
            type: this.getVideoType()
          }],
          techOrder: ['html5']
        };
        
        this.player = videojs(this.$refs.videoPlayer, videoOptions);
      }

      // Add event listeners
      this.player.on('play', this.onPlay);
      this.player.on('pause', this.onPause);
      this.player.on('ended', this.onVideoEnded);
      
      // Log errors for debugging
      this.player.on('error', (error) => {
        console.error('Video.js player error:', error);
      });
    },

    togglePlayPause() {
      if (this.videoEnded) {
        // If the video has ended, reset it rather than trying to play
        this.$emit('video-watched', this.video);
        return;
      }
      
      if (this.player) {
        if (this.player.paused()) {
          this.player.play();
        } else {
          this.player.pause();
        }
      }
    },
    
    getVideoUrl() {
      const url = this.video.url;
      
      // Handle YouTube URLs specifically with strict parameters
      if (this.isYouTubeVideo()) {
        const videoId = this.extractYouTubeId(url);
        if (videoId) {
          // All these parameters help lock down the YouTube player
          // Adding endscreen=0 and additional parameters to suppress end screens
          return `https://www.youtube-nocookie.com/embed/${videoId}?rel=0&modestbranding=1&iv_load_policy=3&showinfo=0&controls=0&disablekb=1&playsinline=1&autoplay=0&loop=0&enablejsapi=1&origin=${encodeURIComponent(window.location.origin)}&widget_referrer=${encodeURIComponent(window.location.href)}&playlist=${videoId}`;
        }
      }
      
      // Return the original URL for other video types
      return url;
    },
    
    getVideoType() {
      const url = this.video.url.toLowerCase();
      
      // Determine video type based on URL
      if (this.isYouTubeVideo()) {
        return 'video/youtube';
      } else if (url.endsWith('.mp4')) {
        return 'video/mp4';
      } else if (url.endsWith('.webm')) {
        return 'video/webm';
      } else if (url.endsWith('.ogg') || url.endsWith('.ogv')) {
        return 'video/ogg';
      } else if (url.endsWith('.m3u8')) {
        return 'application/x-mpegURL';
      } else if (url.endsWith('.mpd')) {
        return 'application/dash+xml';
      } else {
        // Try to determine from URL or default to mp4
        console.warn('Could not determine video type from URL:', url);
        return 'video/mp4';
      }
    },
    
    getVideoPoster() {
      // If the video has a thumbnail property, use it
      if (this.video.thumbnail) {
        return this.video.thumbnail;
      }
      
      // For YouTube videos, we can generate thumbnails
      if (this.isYouTubeVideo()) {
        const videoId = this.extractYouTubeId(this.video.url);
        if (videoId) {
          return `https://img.youtube.com/vi/${videoId}/0.jpg`;
        }
      }
      
      // Return a default placeholder if no thumbnail is available
      return '/placeholder-video.jpg';
    },
    
    isYouTubeVideo() {
      const url = this.video.url.toLowerCase();
      return url.includes('youtube.com') || url.includes('youtu.be');
    },
    
    extractYouTubeId(url) {
      const match = url.match(/(?:\/embed\/|v=|\/\d{2,4}\/|youtu\.be\/|\/v\/|\/e\/|\/u\/\d{1,2}\/|\/embed\/|\/v\/|e\/|u\/\d{1,2}\/|^youtu\.be\/)([^#?\s]+)/);
      return match && match[1].length === 11 ? match[1] : null;
    },
    
    onPlay() {
      // Reset the ended state when playing
      this.videoEnded = false;
      
      // Request fullscreen when playing
      if (!this.fullscreen) {
        try {
          const elem = this.$el;
          if (elem.requestFullscreen) {
            elem.requestFullscreen();
          } else if (elem.webkitRequestFullscreen) { /* Safari */
            elem.webkitRequestFullscreen();
          } else if (elem.msRequestFullscreen) { /* IE11 */
            elem.msRequestFullscreen();
          }
          this.fullscreen = true;
        } catch (e) {
          console.error('Could not enter fullscreen mode:', e);
        }
      }
    },
    
    onPause() {
      // Exit fullscreen when paused
      if (this.fullscreen) {
        try {
          if (document.exitFullscreen) {
            document.exitFullscreen();
          } else if (document.webkitExitFullscreen) { /* Safari */
            document.webkitExitFullscreen();
          } else if (document.msExitFullscreen) { /* IE11 */
            document.msExitFullscreen();
          }
          this.fullscreen = false;
        } catch (e) {
          console.error('Could not exit fullscreen mode:', e);
        }
      }
    },
    
    onVideoEnded() {
      this.videoEnded = true;
      
      // Create and display a completely opaque overlay
      const overlayElement = document.createElement('div');
      overlayElement.classList.add('full-video-overlay');
      overlayElement.innerHTML = `
        <div class="overlay-content">
          <p>Video Complete</p>
          <button class="button is-danger" id="video-end-btn">Done</button>
        </div>
      `;
      
      // Append overlay to video container
      this.$el.querySelector('.video-player').appendChild(overlayElement);
      
      // Add event listener to the button
      document.getElementById('video-end-btn').addEventListener('click', () => {
        // Mark as watched and emit event
        this.watched = true;
        this.$emit('video-watched', this.video);
        
        // Remove overlay
        overlayElement.remove();
      });
      
      // Exit fullscreen
      if (this.fullscreen) {
        try {
          if (document.exitFullscreen) {
            document.exitFullscreen();
          } else if (document.webkitExitFullscreen) {
            document.webkitExitFullscreen();
          } else if (document.msExitFullscreen) {
            document.msExitFullscreen();
          }
          this.fullscreen = false;
        } catch (e) {
          console.error('Could not exit fullscreen mode:', e);
        }
      }
    },
    
    onFullscreenChange() {
      // Update fullscreen state based on document.fullscreenElement
      this.fullscreen = !!document.fullscreenElement || 
                        !!document.webkitFullscreenElement || 
                        !!document.mozFullScreenElement || 
                        !!document.msFullscreenElement;
      
      // If exited fullscreen manually, pause the video
      if (!this.fullscreen && this.player && !this.player.paused()) {
        this.player.pause();
      }
    }
  },
  
  mounted() {
    // Add a small delay to ensure the DOM is fully loaded
    setTimeout(() => {
      this.setupPlayer();
      
      // Add fullscreen change event listener
      document.addEventListener('fullscreenchange', this.onFullscreenChange);
      document.addEventListener('webkitfullscreenchange', this.onFullscreenChange);
      document.addEventListener('mozfullscreenchange', this.onFullscreenChange);
      document.addEventListener('MSFullscreenChange', this.onFullscreenChange);
    }, 100);
  },
  
  beforeUnmount() {
    // Clean up player resources when component is destroyed
    if (this.player) {
      this.player.dispose();
    }
    
    // Remove fullscreen change event listeners
    document.removeEventListener('fullscreenchange', this.onFullscreenChange);
    document.removeEventListener('webkitfullscreenchange', this.onFullscreenChange);
    document.removeEventListener('mozfullscreenchange', this.onFullscreenChange);
    document.removeEventListener('MSFullscreenChange', this.onFullscreenChange);
  }
}
</script>

